private boolean isOwnerRemovedOrDiscarded() {
    AreaEffectCloudEntityAccessor accessor = (AreaEffectCloudEntityAccessor)this;
    if (accessor.apugli$getOwner() == null) {
        return false;
    }
    return accessor.apugli$getOwner().getRemovalReason() == RemovalReason.KILLED || accessor.apugli$getOwner().getRemovalReason() == RemovalReason.DISCARDED;
}

public CustomAreaEffectCloud createCloud(SerializableData.Instance data, Entity owner, Entity levelGetter, double x, double y, double z) {
    CustomAreaEffectCloud cloud = new CustomAreaEffectCloud(levelGetter.level(), x, y, z);
    if (owner instanceof LivingEntity livingOwner)
        cloud.setOwner(livingOwner);
    cloud.setEntityId(data.getId("entity_id"));
    cloud.setRadius(data.getFloat("radius"));
    cloud.setRadiusOnUse(data.getFloat("radius_on_use"));
    cloud.setWaitTime(data.getInt("wait_time"));
    cloud.setDuration(data.getInt("duration"));
    cloud.setRadiusPerTick(data.getFloat("radius_per_tick"));
    cloud.setHeightIncrease(data.getDouble("height_increase"));
    cloud.setOwnerCloudBiEntityAction(data, "owner_cloud_bientity_action");
    cloud.setCloudTargetBiEntityAction(data, "cloud_target_bientity_action");
    cloud.setOwnerTargetBiEntityAction(data, "owner_target_bientity_action");
    cloud.setParticle(data.get("particle"));
    cloud.setBiEntityCondition(data, "bientity_condition");
    cloud.setOwnerTargetBiEntityCondition(data, "owner_target_bientity_condition");
    ((AreaEffectCloudEntityAccessor)cloud).apugli$setReapplicationDelay(data.getInt("reapplication_delay"));
    if (data.isPresent("powers_to_apply")) {
        data.<List<?>>get("powers_to_apply").forEach(cloud::addPowerToApply);
    }
    return cloud;
}

@Override
public void execute(SerializableData.Instance data, Entity entity) {
    CustomAreaEffectCloud cloud = createCloud(data, entity, entity, entity.getX(), entity.getY(), entity.getZ());
    entity.level().addFreshEntity(cloud);
}

